11	export default async function ItemPage({
12	  params,
13	}: {
14	  params: Promise<{ itemId: string }>;
15	}) {
16	  const { itemId } = await params;
17	  const supabase = await createClient();
18	  const {
19	    data: { user },
20	  } = await supabase.auth.getUser();
21	  if (!user) redirect("/");
22	
23	  const { data: item } = await supabase.from("items").select("*").eq("id", itemId).single();
24	  if (!item) notFound();
25	
26	  // The rest of the wardrobe — used for "Goes with" and the brand suggestions.
27	  const { data: closetRows } = await supabase.from("items").select("*").eq("archived", false);
28	  const closet = closetRows ?? [];
29	
30	  /**
31	   * Wear history for ONE item, in two steps on purpose.
32	   *
33	   * A wear is logged against an OUTFIT, never an item, so an item's wear count
34	   * is "how many logged outfits contained it". `wear_logs` and `outfit_items`
35	   * are NOT directly related — both hang off `outfits` — so PostgREST cannot
36	   * embed one in the other, and an `outfit_items!inner(...)` join silently
37	   * returned zero rows for an item that had genuinely been worn. Two explicit
38	   * queries are obviously correct where that embed was quietly wrong.
39	   */
40	  const { data: wornIn } = await supabase
41	    .from("outfit_items")
42	    .select("outfit_id")
43	    .eq("item_id", itemId);
44	  const outfitIds = (wornIn ?? []).map((r) => r.outfit_id);
45	  const { data: logs } = outfitIds.length
46	    ? await supabase.from("wear_logs").select("worn_on").in("outfit_id", outfitIds)
47	    : { data: [] };
48	
49	  const { data: profile } = await supabase
50	    .from("profiles")
51	    .select("location_timezone")
52	    .eq("id", user.id)
53	    .single();
54	  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
55	
56	  const stats = itemWearStats(logs ?? [], item.price, today);
57	
58	  const pairIds = goesWith(
59	    { id: item.id, category: item.category, colors: item.colors ?? [], formality: item.formality },
60	    closet.map((i) => ({
61	      id: i.id,
62	      category: i.category,
63	      colors: i.colors ?? [],
64	      formality: i.formality,
65	    })),
66	  );
67	  const byId = new Map(closet.map((i) => [i.id, i]));
68	  const pairs = pairIds.flatMap((id) => {
69	    const row = byId.get(id);
70	    return row ? [row] : [];
71	  });
72	
73	  const signed = await signItemImages([item, ...pairs].map(displayPath));
74	
75	  const goesWithCards: GoesWithCard[] = pairs.map((i) => ({
76	    id: i.id,
77	    name: i.name ?? i.subcategory ?? i.category,
78	    imageUrl: signed.get(displayPath(i)) ?? "",
79	  }));
80	
81	  // Distinct brands already in the closet → autocomplete suggestions.
82	  const brandSuggestions = [...new Set(closet.map((i) => i.brand).filter(Boolean) as string[])];
