3	import { useState, useTransition } from "react";
4	import { useRouter } from "next/navigation";
5	import { styleWithItem } from "@/app/closet/[itemId]/style-actions";
6	import { UpgradeSheet } from "@/components/billing/upgrade-sheet";
7	
8	/**
9	 * The one primary action on item detail (Fitcheck.dc.html:654).
10	 *
11	 * The outcome is a STATE, not an exception: "this is a Pro feature" and "there
12	 * is not enough else in your closet yet" are both real answers, and a thrown
13	 * error would render as a dead button with no explanation.
14	 *
15	 * The button stays VISIBLE and enabled for free users on purpose. Nobody buys a
16	 * feature they have never seen, and this screen — the canonical one — is where
17	 * the want is felt. Tapping it explains the feature rather than doing nothing.
18	 */
19	export function StyleCta({ itemId, styledToday }: { itemId: string; styledToday: boolean }) {
20	  const router = useRouter();
21	  const [pending, start] = useTransition();
22	  const [message, setMessage] = useState<string | null>(null);
23	  // A Pro gate and "your closet is too thin for this yet" are different answers
24	  // and get different weight: the first is a sheet that explains and sells, the
25	  // second is a quiet line, because there is nothing to buy — you add a piece.
26	  const [upgrade, setUpgrade] = useState<string | null>(null);
27	  /**
28	   * Offered only once a set exists — before that there is nothing to compare
29	   * against. Seeded from the SERVER, not just from this session: tapping the
30	   * primary navigates to the look, so a flag set on that tap is gone by the
31	   * time the user comes back and this remounts. Session state alone meant the
32	   * control could never appear at all.
33	   */
34	  const [styled, setStyled] = useState(styledToday);
35	
36	  function run(regenerate: boolean) {
37	    start(async () => {
38	      setMessage(null);
39	      setUpgrade(null);
40	      const res = await styleWithItem(itemId, { regenerate });
41	      if (res.status === "ok") {
42	        setStyled(true);
43	        router.push(`/outfits/${res.outfitIds[0]}`);
44	      }
45	      // The reason is rendered verbatim, never re-worded here. It used to read
46	      // "that's today's stylings used — back tomorrow", written when styling
47	      // was assumed to share the daily generation allowance. It is a Pro
48	      // capability, so tomorrow gives a free user no more of them — the old
49	      // copy told people to wait for something that would never arrive.
50	      else if (res.status === "limited") setUpgrade(res.message);
51	      else setMessage(res.message);
52	    });
53	  }
54	
55	  return (
56	    <div className="flex flex-1 flex-col">
57	      <button
58	        type="button"
59	        disabled={pending}
60	        onClick={() => run(false)}
61	        className="min-h-[54px] w-full rounded-[14px] bg-foreground text-[15.5px] font-semibold text-canvas disabled:opacity-70"
62	      >
63	        {pending ? "Styling…" : "Style an outfit with this"}
64	      </button>
65	
66	      {/* A bounded secondary with WORDS, below the primary — the shape PR #20
67	          arrived at after an icon-only Regenerate was tried and rejected,
68	          because nothing tells you a ⟳ means "spend an AI call". It exists
69	          because the cache is right but silent: tapping again returned the
70	          identical look with no explanation. */}
71	      {styled && (
72	        <button
73	          type="button"
74	          disabled={pending}
75	          onClick={() => run(true)}
76	          className="mx-auto mt-2 min-h-[44px] rounded-full px-4 text-[13px] text-muted-foreground shadow-[inset_0_0_0_1px_var(--hairline-4)] disabled:opacity-60"
77	        >
78	          {pending ? "Styling…" : "Try another look"}
79	        </button>
80	      )}
81	
82	      {message && (
83	        <p role="status" className="mt-2 text-center text-xs text-muted-foreground">
84	          {message}
85	        </p>
86	      )}
87	
88	      <UpgradeSheet
89	        open={Boolean(upgrade)}
90	        title="Style a look around any piece"
91	        body={upgrade ?? ""}
92	        onClose={() => setUpgrade(null)}
93	      />
94	    </div>
95	  );
96	}
