3	import { useState, useTransition } from "react";
4	import { archiveItem } from "@/app/closet/[itemId]/actions";
5	import type { Tags } from "@/lib/ai/tagging-schema";
6	
7	import { ItemView, type GoesWithCard } from "./item-view";
8	import { ItemEditSheet } from "./item-edit-sheet";
9	import { StyleCta } from "./style-cta";
10	
11	export type DetailItem = {
12	  id: string;
13	  name: string | null;
14	  brand: string | null;
15	  category: Tags["category"];
16	  subcategory: string | null;
17	  colors: string[];
18	  material: string | null;
19	  texture: string | null;
20	  pattern: string | null;
21	  price: number | null;
22	  formality: number | null;
23	  seasons: string[];
24	};
25	
26	/**
27	 * The item detail shell.
28	 *
29	 * This file used to BE the tag form. The design's item detail is read-first —
30	 * cutouts are the hero, the stat tiles answer "how do I actually wear this?",
31	 * and editing sits behind `⋯`. So this component now owns only the switch
32	 * between the two: `ItemView` reads, `ItemEditSheet` writes.
33	 */
34	export function ItemDetail({
35	  item,
36	  imageUrl,
37	  brandSuggestions,
38	  stats,
39	  goesWith,
40	  styledToday,
41	}: {
42	  item: DetailItem;
43	  imageUrl: string;
44	  brandSuggestions: string[];
45	  stats: { wears: number; costPerWear: string | null; lastWorn: string };
46	  goesWith: GoesWithCard[];
47	  /** Whether this piece already has a styled set today — read on the server. */
48	  styledToday: boolean;
49	}) {
50	  const [editing, setEditing] = useState(false);
51	  const [, start] = useTransition();
52	
53	  function archive() {
54	    if (!confirm("Remove this piece from your closet?")) return;
55	    start(async () => {
56	      await archiveItem(item.id);
57	    });
58	  }
59	
60	  return (
61	    <>
62	      <ItemView
63	        item={item}
64	        imageUrl={imageUrl}
65	        stats={stats}
66	        goesWith={goesWith}
67	        onEdit={() => setEditing(true)}
68	        onArchive={archive}
69	        // Built HERE, not passed down from the page. `page.tsx` is a Server
70	        // Component, and a JSX element handed across the RSC boundary is
71	        // serialised — React cannot give it positional identity and warns that
72	        // every child in a list needs a key. Creating it inside this client
73	        // component keeps ItemView presentational without that round trip.
74	        styleCta={<StyleCta itemId={item.id} styledToday={styledToday} />}
75	      />
76	      {editing && (
77	        <ItemEditSheet
78	          item={item}
79	          brandSuggestions={brandSuggestions}
80	          onClose={() => setEditing(false)}
81	        />
82	      )}
83	    </>
84	  );
85	}
